--
-- Name: symbol_candles_monthly; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.symbol_candles_monthly AS
 SELECT symbol_id,
    'monthly'::text AS resolution,
    date_trunc('month'::text, ts) AS ts,
    (array_agg(open ORDER BY symbol_candles.ts))[1] AS open,
    max(high) AS high,
    min(low) AS low,
    (array_agg(close ORDER BY symbol_candles.ts DESC))[1] AS close,
    (array_agg(adjusted_close ORDER BY symbol_candles.ts DESC) FILTER (WHERE (adjusted_close IS NOT NULL)))[1] AS adjusted_close,
    sum(volume) AS volume
   FROM public.symbol_candles
  WHERE ((resolution)::text = 'daily'::text)
  GROUP BY symbol_id, (date_trunc('month'::text, ts));


